PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
pq.offer(2_000_000_000);
pq.offer(-1_000_000_000);
System.out.println(pq.peek());

int[] a = {5}, b = {3};
PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
pq.offer(a);
pq.offer(b);
a[0] = 1;              // a should now be the smallest
System.out.println(pq.poll()[0]);

hard.code:
PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder()); // smaller half
PriorityQueue<Integer> high = new PriorityQueue<>();                          // larger half

void addNum(int x) {
    if (low.size() <= high.size()) low.offer(x); else high.offer(x);
}

double findMedian() {
    return low.size() > high.size() ? low.peek() : (low.peek() + (long) high.peek()) / 2.0;
}
